sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // MSCUSTODY-3144
    // g_scratchpad.LastPositionsRefreshDateTime = current.trade_id.last_positions_refresh_date_time;
    g_scratchpad.LastPositionsRefreshDateTime = current.trade_id.last_positions_refresh_date_time.getDisplayValue();
    g_scratchpad.Sourcesystem = current.trade_id.source_system;
    g_scratchpad.syspro_sourcesystem = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_ghss');
    g_scratchpad.syspro_sourcesystem_gcs = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_gcs'); // MSSCUSTODY-5521

	// MSSCUSTODY-5855
    var siteCode = current.trade_id.trade_id.slice(0,7);
    gs.getSession().putClientData('siteCode', siteCode);

})(current, previous);
